     "text": "import numpy as np\nimport torch\n\nrng = np.random.default_rng(0)\nX = rng.normal(size=(8, 4)); y = rng.integers(0, 3, size=8)          # 8 объектов, 3 класса\nW1, b1 = rng.normal(size=(5, 4)) * 0.5, np.zeros(5)\nW2, b2 = rng.normal(size=(3, 5)) * 0.5, np.zeros(3)\n\n# прямой проход: запоминаем промежуточные значения\nZ1 = X @ W1.T + b1; H = np.maximum(0, Z1)\nZ2 = H @ W2.T + b2\nP = np.exp(Z2 - Z2.max(1, keepdims=True)); P /= P.sum(1, keepdims=True)\nloss = -np.log(P[np.arange(8), y]).mean()\n\n# обратный проход: от потерь к входу\nG2 = P.copy(); G2[np.arange(8), y] -= 1; G2 /= 8      # ∂L/∂Z2 = (p − onehot) / B\ndW2, db2 = G2.T @ H, G2.sum(0)\nGH = G2 @ W2                                         # градиент по выходу ReLU\nG1 = GH * (Z1 > 0)                                   # ReLU пропускает только там, где Z1 > 0\ndW1, db1 = G1.T @ X, G1.sum(0)\n\n# то же самое через autograd\nt = lambda a: torch.tensor(a, dtype=torch.float64, requires_grad=True)\ntW1, tb1, tW2, tb2 = t(W1), t(b1), t(W2), t(b2)\nlogits = torch.relu(torch.tensor(X) @ tW1.T + tb1) @ tW2.T + tb2\ntl = torch.nn.functional.cross_entropy(logits, torch.tensor(y))\ntl.backward()\nprint('loss вручную / torch:', round(loss, 6), round(tl.item(), 6))\nfor name, mine, ref in [('W1', dW1, tW1), ('b1', db1, tb1), ('W2', dW2, tW2), ('b2', db2, tb2)]:\n    print(f'max |разница| для {name}: {np.abs(mine - ref.grad.numpy()).max():.1e}')",
